await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });

const faqData = await browserjs(tabId, () => {
  // Check schema.org or accordion elements
  const schemas = Array.from(document.querySelectorAll('script[type="application/ld+json"]')).map(s => {
    try { return JSON.parse(s.textContent); } catch(e) { return null; }
  });

  // Also find any elements whose id or class has faq or accordion
  const accordions = Array.from(document.querySelectorAll('.accordion, .faq, [data-faq], [class*="faq"], [class*="accordion"]')).map(el => el.innerText);

  // Search for the word "valet" in the entire HTML source
  const html = document.body.innerHTML;
  const valetMatches = [];
  let idx = 0;
  while ((idx = html.toLowerCase().indexOf('valet', idx)) !== -1) {
    valetMatches.push(html.slice(Math.max(0, idx - 100), idx + 200));
    idx += 5;
    if (valetMatches.length > 5) break;
  }

  return { schemas, accordions: accordions.slice(0, 5), valetMatches };
});
console.log(JSON.stringify(faqData, null, 2));

