const tabId = 787784616;
const hotels = [
  "Fairmont Pittsburgh",
  "Omni William Penn Hotel",
  "Kimpton Hotel Monaco Pittsburgh",
  "Wyndham Grand Pittsburgh Downtown",
  "The Priory Hotel Pittsburgh",
  "Drury Plaza Hotel Pittsburgh Downtown",
  "The Westin Pittsburgh",
  "Embassy Suites by Hilton Pittsburgh Downtown"
];

const results = {};

for (const h of hotels) {
  const url = `https://www.google.com/travel/search?q=${encodeURIComponent(h)}&checkin=2026-10-21&checkout=2026-10-23`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 8000 });

  const text = await browserjs(tabId, () => {
    // Look for price elements
    const body = document.body.innerText;
    // Find lines with $
    const lines = body.split('\n').map(l => l.trim()).filter(Boolean);
    const priceLines = lines.filter(l => /^\$[0-9]+/.test(l) || l.includes('/night') || l.includes('total'));
    return {
      title: document.title,
      priceLines: priceLines.slice(0, 10),
      snippet: body.slice(0, 1000)
    };
  });
  results[h] = text;
}

console.log(JSON.stringify(results, null, 2));

